local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/Action/ActionDarkDreamMainDialog.prefab > name: Cell
---@class ActionDarkDreamMainBtnCell
---@field Env                           	ActionDarkDreamMainBtnCell              
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field redPoint                      	UnityEngine.RectTransform               
---@field ImgLock                       	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
---@field Cell                          	UnityEngine.RectTransform               
local ActionDarkDreamMainBtnCell = Class('ActionDarkDreamMainBtnCell')
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
function ActionDarkDreamMainBtnCell:__init()
    self.index = nil
    self.callBack = nil
end

function ActionDarkDreamMainBtnCell:__delete()
    self.index = nil
    self.callBack = nil
end

function ActionDarkDreamMainBtnCell:Awake()
    SetButtonAction(self.Cell.gameObject,Bind(self,self.OnBtnClick))
end

function ActionDarkDreamMainBtnCell:SetCallBackAndIndex(callBack,index)
    self.callBack = callBack
    self.index = index
end

function ActionDarkDreamMainBtnCell:PlayHideAni()
    CfUtils.PlayAnimation(self.controller.gameObject,"UI_Common_List_Cell_Hide")
end

function ActionDarkDreamMainBtnCell:RefreshShow(data,selectIndex,vo,maxCount)
    self.data = data
    self.vo = vo
    self.isUnLock = self:IsUnLock()

    KTool.SetActive(self.ImgLock.gameObject,not self.isUnLock)
    CfUtils.FillImage(self.ImgSelect,vo.iconLight)
    CfUtils.FillImage(self.ImgIcon,vo.iconDark)

    KTool.SetActive(self.ImgSelect.gameObject,self.index == selectIndex)
    if self.index == selectIndex then
        self:OnBtnClick()
    end

    KTool.SetActive(self.ImgLine,not (self.index == maxCount))

    self:RefreshRedPoint()
end

function ActionDarkDreamMainBtnCell:IsUnLock()
    if checkNumber(self.vo.condition) == 0 then
        return true
    else
        local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(self.vo.condition)
        local isUnLock = ChaoticRecallUtils.GetIsPassById(nodeVo.groupId,self.vo.condition)
        return isUnLock
    end
    return true
end

function ActionDarkDreamMainBtnCell:RefreshRedPoint()
    local isUnLock = self:IsUnLock()
    local isHaveRedPoint = false
    if isUnLock then
        isHaveRedPoint = ChaoticRecallUtils.IsGroupHaveRedPoint(self.data.groupId,self.index)
    end
    KTool.SetActive(self.redPoint.gameObject,isHaveRedPoint)
end

function ActionDarkDreamMainBtnCell:DoSelect()
    CfUtils.PlayAnimation(self.Root.gameObject,"ActionDarkDreamMainDialog_Default")
    KTool.SetActive(self.ImgSelect.gameObject,false)
end

function ActionDarkDreamMainBtnCell:Select()
    CfUtils.PlayAnimation(self.Root.gameObject,"ActionDarkDreamMainDialog_Select")
    KTool.SetActive(self.ImgSelect.gameObject,true)
end

function ActionDarkDreamMainBtnCell:OnBtnClick()
    if self.isUnLock then
        if self.callBack then
            self.callBack(self.index,self.data.groupId,self.vo)
        end
    else
        local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(self.vo.condition)
        if not isNull(nodeVo) then
            GameUtils.Toast(localize("请先通关前置关卡_name_",{_name_ = nodeVo.name}))
        end
    end
end

function ActionDarkDreamMainBtnCell:PlayShowAni()
    CfUtils.PlayDelayShowAnimate(self.Cell, 1, (self.index or 1) * 0.1,nil,"ActionDarkDreamMainDialog_BtnCell_Show")
end

function ActionDarkDreamMainBtnCell:Start()
end

function ActionDarkDreamMainBtnCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamMainBtnCell